mapper.select:
SELECT mp.*, mm.start_time, mm.duration, mm.game_mode, mm.lobby_type,
       mm.mvp_steam_id AS mvp_steam_id, mm.fmvp_steam_id AS fmvp_steam_id
FROM match_player mp
LEFT JOIN match_main mm ON mp.match_id = mm.match_id

    LEFT JOIN match_detail md ON mp.match_id = md.match_id



        AND mp.steam_id = #{steamId}


        AND mm.game_mode = #{gameMode}


        AND mp.hero_id = #{heroId}


        AND md.raw_json IS NOT NULL AND md.raw_json LIKE '%damage_inflictor%'


        AND (md.raw_json IS NULL OR md.raw_json NOT LIKE '%damage_inflictor%')




        ORDER BY ${sortField} ${sortOrder}


        ORDER BY mm.start_time DESC NULLS LAST, mp.id DESC


OFFSET #{offset} LIMIT #{limit}

SELECT COUNT(*)
FROM match_player mp
LEFT JOIN match_main mm ON mp.match_id = mm.match_id

    LEFT JOIN match_detail md ON mp.match_id = md.match_id



        AND mp.steam_id = #{steamId}


        AND mm.game_mode = #{gameMode}


        AND mp.hero_id = #{heroId}


        AND md.raw_json IS NOT NULL AND md.raw_json LIKE '%damage_inflictor%'


        AND (md.raw_json IS NULL OR md.raw_json NOT LIKE '%damage_inflictor%')

SELECT t.hero_id, COUNT(*) as games, ROUND(100.0 * SUM(CASE WHEN t.win THEN 1 ELSE 0 END) / COUNT(*), 1) as win_rate, ROUND(AVG(t.kills), 2) as avg_kills, ROUND(AVG(t.deaths), 2) as avg_deaths, ROUND(AVG(t.assists), 2) as avg_assists, ROUND(AVG(t.gold_per_min), 0) as avg_gpm, ROUND(AVG(t.xp_per_min), 0) as avg_xpm, COUNT(*) FILTER (WHERE t.rn <= 20) as recent_games_20, ROUND(100.0 * SUM(CASE WHEN t.rn <= 20 AND t.win THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN t.rn <= 20 THEN 1 ELSE 0 END), 0), 1) as recent_win_rate_20, ROUND(AVG(t.kills) FILTER (WHERE t.rn <= 20), 2) as recent_kills_20, ROUND(AVG(t.deaths) FILTER (WHERE t.rn <= 20), 2) as recent_deaths_20, ROUND(AVG(t.assists) FILTER (WHERE t.rn <= 20), 2) as recent_assists_20, COUNT(*) FILTER (WHERE t.rn <= 50) as recent_games_50, ROUND(100.0 * SUM(CASE WHEN t.rn <= 50 AND t.win THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN t.rn <= 50 THEN 1 ELSE 0 END), 0), 1) as recent_win_rate_50, ROUND(AVG(t.kills) FILTER (WHERE t.rn <= 50), 2) as recent_kills_50, ROUND(AVG(t.deaths) FILTER (WHERE t.rn <= 50), 2) as recent_deaths_50, ROUND(AVG(t.assists) FILTER (WHERE t.rn <= 50), 2) as recent_assists_50 FROM ( SELECT mp.*, mm.start_time, ROW_NUMBER() OVER ( PARTITION BY mp.steam_id, mp.hero_id ORDER BY mm.start_time DESC NULLS LAST ) as rn FROM match_player mp INNER JOIN match_main mm ON mp.match_id = mm.match_id WHERE mp.steam_id = #{steamId}
AND mm.lobby_type = 0 AND mm.game_mode != 23
AND mm.lobby_type = 7 AND mm.game_mode != 23
AND mm.game_mode = 23
AND mm.start_time >= #{startTime}
AND mm.start_time <= #{endTime}
) t GROUP BY t.hero_id HAVING COUNT(*) >= #{minMatches} ORDER BY
win_rate games
ASC DESC

SELECT mp.match_id FROM match_player mp WHERE mp.steam_id IN
#{sid}
GROUP BY mp.match_id HAVING COUNT(DISTINCT mp.steam_id) = #{count} ORDER BY mp.match_id DESC LIMIT 50

SELECT mp1.match_id FROM match_player mp1 WHERE mp1.steam_id IN
#{sid}
AND EXISTS ( SELECT 1 FROM match_player mp2 WHERE mp2.match_id = mp1.match_id AND mp2.steam_id = #{opponentId} AND mp2.win IS DISTINCT FROM mp1.win ) GROUP BY mp1.match_id HAVING COUNT(DISTINCT mp1.steam_id) = #{count} ORDER BY mp1.match_id DESC LIMIT 50

SELECT
    #{steamId} AS steam_id,
    COUNT(*) FILTER (WHERE mm.mvp_steam_id = #{steamId}) AS mvp,
    COUNT(*) FILTER (WHERE mm.fmvp_steam_id = #{steamId}) AS fmvp
FROM match_main mm
WHERE mm.match_id IN (
    SELECT mp.match_id FROM match_player mp
    JOIN match_main mm2 ON mp.match_id = mm2.match_id
    WHERE mp.steam_id = #{steamId}
    AND NOT EXISTS (
        SELECT 1 FROM match_player mp2
        WHERE mp2.match_id = mp.match_id
        AND mp2.steam_id IN

            #{sid}

    )
    AND mm2.game_mode = #{gameMode}
)
AND mm.game_mode = #{gameMode}

SELECT COUNT(*) AS total, SUM(CASE WHEN mp.win = true THEN 1 ELSE 0 END) AS wins, SUM(CASE WHEN mp.win = false THEN 1 ELSE 0 END) AS losses FROM match_player mp JOIN match_main mm ON mp.match_id = mm.match_id WHERE mp.steam_id = #{steamId} AND mm.game_mode = #{gameMode} AND NOT EXISTS ( SELECT 1 FROM match_player mp2 WHERE mp2.match_id = mp.match_id AND mp2.steam_id IN
#{sid}
)

SELECT COUNT(*) AS total, SUM(CASE WHEN mp.win = true THEN 1 ELSE 0 END) AS wins, SUM(CASE WHEN mp.win = false THEN 1 ELSE 0 END) AS losses
, CASE WHEN mm.game_mode = 23 THEN 'turbo' ELSE 'pub' END AS game_mode
FROM match_player mp JOIN match_main mm ON mp.match_id = mm.match_id WHERE mp.steam_id = #{steamId}
AND mm.game_mode = #{gameMode}
GROUP BY CASE WHEN mm.game_mode = 23 THEN 'turbo' ELSE 'pub' END

SELECT mp.match_id
FROM match_player mp
WHERE mp.steam_id = #{steamId}
ORDER BY mp.match_id DESC
LIMIT #{limit}

SELECT COUNT(*) FROM (
    SELECT mp.match_id
    FROM match_player mp
    JOIN match_main mm ON mp.match_id = mm.match_id
    WHERE mp.steam_id = #{steamId}
    AND mm.game_mode = #{gameMode}
    AND NOT EXISTS (
        SELECT 1 FROM match_player mp2
        WHERE mp2.match_id = mp.match_id
        AND mp2.steam_id IN

            #{sid}

    )
) t

SELECT mp.match_id
FROM match_player mp
JOIN match_main mm ON mp.match_id = mm.match_id
WHERE mp.steam_id = #{steamId}
AND mm.game_mode = #{gameMode}
AND NOT EXISTS (
    SELECT 1 FROM match_player mp2
    WHERE mp2.match_id = mp.match_id
    AND mp2.steam_id IN

        #{sid}

)
ORDER BY mp.match_id DESC
OFFSET #{offset} LIMIT #{limit}
